return $input.all().map(item => {
  const input = item.json;
  const output = { event_id: input.event_id, customer_id: input.customer_id, outcome: 'review', reason: 'Human review required', synthetic: true };
  try {
    const data = typeof input.model_output === 'string' ? JSON.parse(input.model_output) : input.model_output;
    const keys = ['status', 'summary', 'confidence', 'next_action'];
    if (!data || typeof data !== 'object' || Array.isArray(data) || Object.keys(data).sort().join('|') !== [...keys].sort().join('|')) throw new Error('Unexpected analysis fields');
    if (!['new', 'quote_requested', 'follow_up', 'resolved'].includes(data.status)) throw new Error('Unsupported status');
    if (!['none', 'follow_up', 'review'].includes(data.next_action)) throw new Error('Unsupported action');
    if (typeof data.confidence !== 'number' || !Number.isFinite(data.confidence) || data.confidence < 0 || data.confidence > 1) throw new Error('Invalid confidence');
    if (typeof data.summary !== 'string' || !data.summary.trim() || data.summary.length > 2000) throw new Error('Invalid summary');
    if (input.approved === true && data.confidence >= 0.8 && data.next_action !== 'review') {
      output.outcome = 'applied'; output.reason = 'Validated and explicitly approved'; output.analysis = data;
    }
  } catch (_) { output.reason = 'Invalid model output; review required'; }
  return { json: output };
});
